<?php

namespace Irios\WooCommerce\Tests;

use Brain\Monkey\Functions;
use Irios\WooCommerce\Events;

/**
 * Cart events generated by the server: one per action (Irios bills per event), with product, price and quantity,
 * only with consent, and delivered to the JS exactly once.
 */
final class EventsTest extends WordPressTestCase {

	protected function setUp(): void {
		parent::setUp();
		$this->given_products( new \WC_Product( 10, 25.5 ), new \WC_Product( 11, 30.0, 'variation' ) );
	}

	private function pending(): array {
		return $this->pending_for( 'visitor-1' );
	}

	private function line( string $id, float $price, int $quantity ): array {
		return array(
			'id'       => $id,
			'price'    => $price,
			'quantity' => $quantity,
		);
	}

	public function test_add_to_cart_with_consent(): void {
		$this->given_consent();

		Events::on_add_to_cart( 'line-a', 10, 2, 0 );

		$this->assertSame(
			array( array( 'id' => 'add-to-cart', 'products' => array( $this->line( '10', 25.5, 2 ) ) ) ),
			$this->pending()
		);
	}

	public function test_add_to_cart_of_a_variation_sends_the_variation(): void {
		$this->given_consent();

		Events::on_add_to_cart( 'line-a', 10, 1, 11 );

		$this->assertSame( '11', $this->pending()[0]['products'][0]['id'] );
	}

	public function test_nothing_is_stored_without_consent(): void {
		$this->given_no_consent();
		$this->wc->session->has_session = false;

		Events::on_add_to_cart( 'line-a', 10, 1, 0 );

		$this->assertSame( array(), $this->transients );
		$this->assertSame( 0, $this->wc->session->cookies_created, 'no session cookie without consent' );
	}

	public function test_first_event_of_a_visitor_starts_the_woocommerce_session(): void {
		$this->given_consent();
		$this->wc->session->has_session = false;

		Events::on_add_to_cart( 'line-a', 10, 1, 0 );

		$this->assertSame( 1, $this->wc->session->cookies_created );
		$this->assertCount( 1, $this->pending() );
	}

	public function test_nothing_happens_without_a_woocommerce_session(): void {
		$this->given_consent();
		$this->wc->session = null;

		Events::on_add_to_cart( 'line-a', 10, 1, 0 );

		$this->assertSame( array(), $this->transients );
	}

	/** Adding something already in the cart: the quantity changes, then WooCommerce fires add-to-cart. One event. */
	public function test_adding_an_existing_line_is_one_event(): void {
		$this->given_consent();
		$this->wc->cart->cart_contents['line-a'] = array( 'data' => new \WC_Product( 10, 25.5 ) );

		Events::on_quantity_update( 'line-a', 3, 1, $this->wc->cart );
		Events::on_add_to_cart( 'line-a', 10, 2, 0 );

		$this->assertSame(
			array( array( 'id' => 'add-to-cart', 'products' => array( $this->line( '10', 25.5, 2 ) ) ) ),
			$this->pending()
		);

		Events::on_add_to_cart( 'line-a', 10, 1, 0 ); // the next add for that line does count
		$this->assertCount( 2, $this->pending() );
	}

	public function test_lowering_the_quantity_is_a_remove_of_the_difference(): void {
		$this->given_consent();
		$this->wc->cart->cart_contents['line-a'] = array( 'data' => new \WC_Product( 10, 25.5 ) );

		Events::on_quantity_update( 'line-a', 1, 4, $this->wc->cart );
		Events::on_quantity_update( 'line-a', 1, 1, $this->wc->cart ); // no change: nothing

		$this->assertSame(
			array( array( 'id' => 'remove-from-cart', 'products' => array( $this->line( '10', 25.5, 3 ) ) ) ),
			$this->pending()
		);
	}

	public function test_removing_a_line_sends_its_product_and_quantity(): void {
		$this->given_consent();
		$this->wc->cart->removed_cart_contents['line-a'] = array( 'product_id' => 10, 'variation_id' => 11, 'quantity' => 2 );

		Events::on_cart_item_removed( 'line-a', $this->wc->cart );
		Events::on_cart_item_removed( 'unknown-line', $this->wc->cart );

		$this->assertSame(
			array( array( 'id' => 'remove-from-cart', 'products' => array( $this->line( '11', 30.0, 2 ) ) ) ),
			$this->pending()
		);
	}

	public function test_cart_view_lists_every_line(): void {
		$this->given_consent();
		Functions\when( 'is_cart' )->justReturn( true );
		$this->wc->cart->cart_contents = array(
			'line-a' => array( 'data' => new \WC_Product( 10, 25.5 ), 'quantity' => 2 ),
			'line-b' => array( 'data' => new \WC_Product( 11, 30.0, 'variation' ), 'quantity' => 1 ),
		);

		Events::on_template_redirect();

		$this->assertSame(
			array( array( 'id' => 'cart-view', 'products' => array( $this->line( '10', 25.5, 2 ), $this->line( '11', 30.0, 1 ) ) ) ),
			$this->pending()
		);
	}

	public function test_no_cart_view_outside_the_cart_or_with_an_empty_cart(): void {
		$this->given_consent();
		Functions\when( 'is_cart' )->justReturn( false );
		$this->wc->cart->cart_contents = array( 'line-a' => array( 'data' => new \WC_Product( 10 ), 'quantity' => 1 ) );
		Events::on_template_redirect();

		Functions\when( 'is_cart' )->justReturn( true );
		$this->wc->cart->cart_contents = array();
		Events::on_template_redirect();

		$this->assertSame( array(), $this->pending() );
	}

	public function test_keeps_only_the_last_20_pending_events(): void {
		$this->given_consent();
		for ( $i = 1; $i <= 25; $i++ ) {
			Events::on_add_to_cart( 'line-' . $i, 10, $i, 0 );
		}

		$pending = $this->pending();
		$this->assertCount( 20, $pending );
		$this->assertSame( 6, $pending[0]['products'][0]['quantity'] );
		$this->assertSame( 25, $pending[19]['products'][0]['quantity'] );
	}

	/** Single-result search without ads: WooCommerce redirects to the product page and the search stays pending. */
	public function test_single_search_result_redirect_keeps_the_search_event(): void {
		$this->given_consent();
		Functions\when( 'get_search_query' )->justReturn( ' stick ' );

		$this->assertTrue( Events::on_single_search_result( true ) );
		$this->assertSame( array( array( 'id' => 'search', 'value' => 'stick' ) ), $this->pending() );

		$this->assertFalse( Events::on_single_search_result( false ) );
		$this->assertCount( 1, $this->pending() );
	}

	/** With Sponsored Products in the search, the results page is kept (the ads and the search event go there). */
	public function test_single_search_result_stays_on_the_results_page_with_search_ads(): void {
		$this->given_consent();
		$this->settings += array(
			'sponsored_enabled' => 'yes',
			'sponsored_slots'   => json_encode( array( array( 'position' => 1, 'id' => 1001, 'auth' => 'abc' ) ) ),
		);
		Functions\when( 'get_search_query' )->justReturn( 'stick' );

		$this->assertFalse( Events::on_single_search_result( true ) );
		$this->assertSame( array(), $this->pending() );
	}

	/** The JS collects the visitor's events only once: the same session customer when saving and when reading. */
	public function test_pending_events_are_delivered_once_to_the_same_visitor(): void {
		$this->given_consent();
		Events::on_add_to_cart( 'line-a', 10, 1, 0 );

		$this->assertSame( array(), Events::take_pending(), 'no WooCommerce session cookie: not this visitor' );

		\WC_Session_Handler::$cookie = array( 'visitor-1', time() + 3600 );
		$this->assertSame( 'add-to-cart', Events::take_pending()[0]['id'] ?? null );
		$this->assertSame( array(), Events::take_pending() );
	}

	public function test_logged_in_customers_use_their_user_id(): void {
		$this->given_consent();
		$this->user_id     = 7;
		$this->wc->session = new \WC_Session_Fake( '7' );
		Events::on_add_to_cart( 'line-a', 10, 1, 0 );

		\WC_Session_Handler::$cookie = array( 'visitor-1', time() + 3600 ); // the session cookie does not count
		$this->assertCount( 1, Events::take_pending() );
	}
}
